import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    public static long fastPow(long base, long exp) {
        long result = 1;
        long current = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * current) % MOD;
            }
            current = (current * current) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(fastPow(p, p - 1));
        } else if (k == 1) {
            System.out.println(fastPow(p, p));
        } else {
            long cycleLength = 1;
            long position = k % p;
            while (position != 1) {
                position = (position * k) % p;
                cycleLength++;
            }
            long count = (p - 1) / cycleLength;
            System.out.println(fastPow(p, count));
        }
        sc.close();
    }
}
